        long[][] dist = new long[10][10];
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 10; j++) {
                dist[i][j] = cost[i][j];
            }
            dist[i][i] = 0;
        }

        for (int k = 0; k < 10; k++) {
            for (int i = 0; i < 10; i++) {
                for (int j = 0; j < 10; j++) {
                    if (dist[i][k] + dist[k][j] < dist[i][j]) {
                        dist[i][j] = dist[i][k] + dist[k][j];
                    }
                }
            }
        }

        long total = 0;
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                char c = grid[i][j];
                if (c != '.' && c != '1') {
                    int d = c - '0';
                    total += dist[d][1];
                }
            }
