public class Main {
    static final long INF = (long) 1e18;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int H = fs.nextInt();
        int W = fs.nextInt();

        long[][] cost = new long[10][10];
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 10; j++) {
                cost[i][j] = fs.nextLong();
            }
        }

        // Floyd-Warshall to find minimum conversion cost between all pairs of digits
        for (int k = 0; k < 10; k++) {
            for (int i = 0; i < 10; i++) {
                for (int j = 0; j < 10; j++) {
                    if (cost[i][j] > cost[i][k] + cost[k][j]) {
                        cost[i][j] = cost[i][k] + cost[k][j];
                    }
                }
            }
        }

        long answer = 0;
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                int x = fs.nextInt();
                if (x == -1) continue; // no digit on this cell
                answer += cost[x][1];
            }
        }

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

